"use client";

import "./radio.css";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import type React from "react";
import { cn } from "@/lib/cn";

import { RadioContext, useRadioContext } from "./radio.context";
import { radioVariants, type RadioVariants } from "./radio.variants";

export type RadioGroupProps = RadioVariants & React.ComponentProps<typeof BaseRadioGroup>;

export const RadioGroup = ({ children, className, size, ...props }: RadioGroupProps) => {
  const slots = radioVariants({ size });

  return (
    <RadioContext.Provider value={{ slots }}>
      <BaseRadioGroup className={cn(slots.group(), className)} {...props}>
        {children}
      </BaseRadioGroup>
    </RadioContext.Provider>
  );
};

export const RadioGroupRoot = RadioGroup;

export type RadioProps = React.ComponentProps<typeof BaseRadio.Root>;

export const RadioRoot = ({ className, ...props }: RadioProps) => {
  const { slots } = useRadioContext();
  return <BaseRadio.Root className={cn(slots.root(), className)} {...props} />;
};

export const RadioItem = RadioRoot;

export type RadioIndicatorProps = React.ComponentProps<typeof BaseRadio.Indicator>;

export const RadioIndicator = ({ className, ...props }: RadioIndicatorProps) => {
  const { slots } = useRadioContext();
  return <BaseRadio.Indicator className={cn(slots.indicator(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const radioVariants = tv({
  slots: {
    group: "radio-group",
    root: "radio",
    indicator: "radio__indicator",
  },
  variants: {
    size: {
      sm: {
        root: "radio--sm",
        indicator: "radio__indicator--sm",
      },
      md: {
        root: "radio--md",
        indicator: "radio__indicator--md",
      },
      lg: {
        root: "radio--lg",
        indicator: "radio__indicator--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type RadioVariants = VariantProps<typeof radioVariants>;

"use client";

import { createContext, useContext } from "react";

import { radioVariants } from "./radio.variants";

export type RadioContext = {
  slots: ReturnType<typeof radioVariants>;
};

export const RadioContext = createContext<RadioContext | null>(null);

export const useRadioContext = () => {
  const context = useContext(RadioContext);
  return context ?? { slots: radioVariants() };
};

.radio-group {
  @apply text-foreground flex flex-col gap-2;
}

.radio {
  @apply border-input bg-background text-primary-foreground focus-visible:outline-ring data-checked:border-primary data-checked:bg-primary data-invalid:border-destructive inline-flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-full border p-0 transition-colors focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50;
}

.radio--sm {
  @apply size-3.5;
}

.radio--md {
  @apply size-4;
}

.radio--lg {
  @apply size-5;
}

.radio__indicator {
  @apply before:bg-primary-foreground flex items-center justify-center before:size-1.5 before:rounded-full data-unchecked:hidden;
}

.radio__indicator--sm::before {
  @apply size-1;
}

.radio__indicator--lg::before {
  @apply size-2;
}

import { RadioGroup, RadioGroupRoot, RadioIndicator, RadioItem, RadioRoot } from "./radio";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/radio/content.md
 */
export const Radio = {
  Group: RadioGroup,
  Indicator: RadioIndicator,
  Item: RadioItem,
  Root: RadioRoot,
};

export { RadioGroup, RadioGroupRoot, RadioIndicator, RadioItem, RadioRoot };

export type { RadioGroupProps, RadioIndicatorProps, RadioProps } from "./radio";
export { RadioContext, useRadioContext } from "./radio.context";
export { type RadioVariants, radioVariants } from "./radio.variants";
